import * as React from "react"

// Arrastre con el puntero, compartido por los controles de audio.
// `onMove` recibe cuánto se movió desde que empezó (dx, dy en px) y el evento.

export function useDrag<T extends Element>(
  onStart: (e: React.PointerEvent<T>) => void,
  onMove: (dx: number, dy: number, e: React.PointerEvent<T>) => void
) {
  const start = React.useRef<{ x: number; y: number } | null>(null)
  const end = () => (start.current = null)
  return {
    onPointerDown(e: React.PointerEvent<T>) {
      e.currentTarget.setPointerCapture(e.pointerId)
      start.current = { x: e.clientX, y: e.clientY }
      onStart(e)
    },
    onPointerMove(e: React.PointerEvent<T>) {
      if (start.current) onMove(e.clientX - start.current.x, e.clientY - start.current.y, e)
    },
    onPointerUp: end,
    onPointerCancel: end,
  }
}

export const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v))
export const snap = (v: number, step: number) => Math.round(v / step) * step

import { Headphones, Power } from "lucide-react"
import { cn } from "@/lib/utils"

// Botones chiquitos de cada control de audio:
//   ⏻  apagar ese control (bypass). Normal = ícono del color de la app.
//      Apretado (control apagado) = fondo del color de la app e ícono blanco.
//   🎧 escuchar sólo eso (solo), el mismo ícono que el solo del instrumento. Prendido = color de la app.
// No usan rojo: el rojo está reservado para borrar.

const base =
  "grid size-6 shrink-0 place-items-center rounded-full border bg-secondary font-mono text-[11px] leading-none font-bold [&_svg]:size-3 text-muted-foreground transition-colors hover:border-ring hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none"

export function PowerButton({
  off,
  onToggle,
  className,
}: {
  off?: boolean
  onToggle: () => void
  className?: string
}) {
  return (
    <button
      type="button"
      data-slot="power-button"
      onClick={onToggle}
      title={off ? "Turn on" : "Turn off"}
      aria-pressed={!!off}
      className={cn(base, off ? "border-brand bg-brand text-brand-foreground hover:border-brand-strong hover:bg-brand-strong hover:text-brand-foreground" : "text-brand hover:text-brand-strong", className)}
    >
      <Power strokeWidth={2.25} />
    </button>
  )
}

export function SoloButton({
  soloed,
  onToggle,
  className,
}: {
  soloed?: boolean
  onToggle: () => void
  className?: string
}) {
  return (
    <button
      type="button"
      data-slot="solo-button"
      onClick={onToggle}
      title="Solo"
      aria-pressed={!!soloed}
      className={cn(base, soloed && "border-brand bg-brand text-brand-foreground hover:text-brand-foreground", className)}
    >
      <Headphones strokeWidth={2.25} />
    </button>
  )
}

export function ParamButtons({
  off,
  onPower,
  soloed,
  onSolo,
}: {
  off?: boolean
  onPower?: () => void
  soloed?: boolean
  onSolo?: () => void
}) {
  if (!onPower && !onSolo) return null
  return (
    <span className="inline-flex gap-1">
      {onPower && <PowerButton off={off} onToggle={onPower} />}
      {onSolo && <SoloButton soloed={soloed} onToggle={onSolo} />}
    </span>
  )
}

import { cn } from "@/lib/utils"
import { Slider } from "@/components/ui/slider"
import { ParamButtons } from "@/components/audio/param-buttons"

// Slider de un parámetro de audio: etiqueta, botones ⏻/S, el slider del sistema y el valor.
// - Doble clic: vuelve al valor por defecto.
// - `log`: recorrido logarítmico (para frecuencias, tiempos).
// - `color`: color del control (por defecto, el de la app).
// - `layout="row"`: compacto, para apilar varios: arriba nombre · valor · botones, abajo el slider a lo ancho.

export function ParamSlider({
  label,
  value,
  min,
  max,
  step = 0.01,
  log = false,
  defaultValue,
  format = String,
  onChange,
  color,
  off,
  onPower,
  soloed,
  onSolo,
  offText = "OFF",
  layout = "stack",
  className,
}: {
  label: string
  value: number
  min: number
  max: number
  step?: number
  log?: boolean
  defaultValue?: number
  format?: (v: number) => string
  onChange: (v: number) => void
  color?: string
  off?: boolean
  onPower?: () => void
  soloed?: boolean
  onSolo?: () => void
  offText?: string
  layout?: "stack" | "row"
  className?: string
}) {
  const toPos = (v: number) =>
    log ? Math.log(v / min) / Math.log(max / min) : v
  const fromPos = (p: number) => (log ? min * Math.pow(max / min, p) : p)

  const slider = (
    <Slider
      aria-label={label}
      color={color}
      min={log ? 0 : min}
      max={log ? 1 : max}
      step={log ? 0.001 : step}
      value={[toPos(value)]}
      onValueChange={([p]) => onChange(fromPos(p))}
      onDoubleClick={() => defaultValue !== undefined && onChange(defaultValue)}
      className={cn(off && "opacity-30")}
    />
  )
  const valueText = (
    <span
      className={cn(
        "font-mono text-sm font-semibold live-number",
        layout === "row" && "shrink-0 text-right",
        off && "text-muted-foreground",
        soloed && "text-brand-text"
      )}
    >
      {off ? offText : format(value)}
    </span>
  )

  if (layout === "row") {
    return (
      <div
        data-slot="param-slider"
        className={cn("flex min-w-0 flex-col gap-1", className)}
      >
        <div className="flex min-h-6 items-center gap-2">
          <span className="min-w-0 flex-1 truncate eyebrow">{label}</span>
          {valueText}
          <ParamButtons
            off={off}
            onPower={onPower}
            soloed={soloed}
            onSolo={onSolo}
          />
        </div>
        {slider}
      </div>
    )
  }

  return (
    <div
      data-slot="param-slider"
      className={cn("flex min-w-0 flex-col gap-1", className)}
    >
      <div className="flex min-h-5 flex-wrap items-center justify-between gap-1">
        <span className="shrink-0 eyebrow">{label}</span>
        <ParamButtons
          off={off}
          onPower={onPower}
          soloed={soloed}
          onSolo={onSolo}
        />
      </div>
      {slider}
      {valueText}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { ParamButtons } from "@/components/audio/param-buttons"

// Perilla giratoria estilo consola.
// - Arrastrá hacia arriba/abajo (con Shift, más fino). Flechas del teclado. Doble clic: reset.
// - `bipolar`: el valor por defecto queda arriba (a las 12) y el arco sale desde ahí,
//   aunque el rango no sea simétrico (ej: EQ de -30 a +6).
// - Aro de 2px; el valor se marca con un punto de 4px.

const ARC = 270
const SIZE = 62 // px (48 + 30%)
const C = SIZE / 2
const R = 23.5

function polar(deg: number): [number, number] {
  const rad = ((deg - 90) * Math.PI) / 180
  return [C + R * Math.cos(rad), C + R * Math.sin(rad)]
}

function arcPath(from: number, to: number) {
  if (Math.abs(to - from) < 0.5) return ""
  const [a, b] = from < to ? [from, to] : [to, from]
  const [x1, y1] = polar(a)
  const [x2, y2] = polar(b)
  return `M ${x1} ${y1} A ${R} ${R} 0 ${b - a > 180 ? 1 : 0} 1 ${x2} ${y2}`
}

export function RotaryKnob({
  label,
  value,
  min,
  max,
  step = 0.5,
  defaultValue = 0,
  bipolar = true,
  format = String,
  onChange,
  color,
  off,
  onPower,
  soloed,
  onSolo,
  offText = "OFF",
  track = 2,
  className,
}: {
  label: string
  value: number
  min: number
  max: number
  step?: number
  defaultValue?: number
  bipolar?: boolean
  format?: (v: number) => string
  onChange: (v: number) => void
  color?: string
  off?: boolean
  onPower?: () => void
  soloed?: boolean
  onSolo?: () => void
  offText?: string
  track?: 2 | 4
  className?: string
}) {
  const drag = React.useRef<{ y: number; n: number } | null>(null)
  const clamp = (v: number) => Math.min(max, Math.max(min, v))
  const toNorm = (v: number) => {
    if (!bipolar) return (v - min) / (max - min)
    return v < defaultValue
      ? 0.5 * ((v - min) / (defaultValue - min))
      : 0.5 + 0.5 * ((v - defaultValue) / (max - defaultValue))
  }
  const fromNorm = (n: number) => {
    n = Math.min(1, Math.max(0, n))
    if (!bipolar) return min + n * (max - min)
    return n < 0.5
      ? min + (n / 0.5) * (defaultValue - min)
      : defaultValue + ((n - 0.5) / 0.5) * (max - defaultValue)
  }
  const angle = -ARC / 2 + toNorm(value) * ARC
  const zeroAngle = bipolar ? 0 : -ARC / 2
  const rad = ((angle - 90) * Math.PI) / 180
  const [px, py] = [C + 10.5 * Math.cos(rad), C + 10.5 * Math.sin(rad)]

  return (
    <div
      data-slot="rotary-knob"
      className={cn("flex w-[76px] flex-col items-center gap-1", className)}
      style={{ "--ctl": color ?? "var(--brand)" } as React.CSSProperties}
    >
      <span className="eyebrow max-w-full truncate">{label}</span>
      <svg
        viewBox={`0 0 ${SIZE} ${SIZE}`}
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        className={cn(
          "size-[62px] cursor-ns-resize touch-none rounded-full outline-none focus-visible:ring-2 focus-visible:ring-(--ctl)",
          off && "opacity-30"
        )}
        onPointerDown={(e) => {
          e.currentTarget.setPointerCapture(e.pointerId)
          drag.current = { y: e.clientY, n: toNorm(value) }
        }}
        onPointerMove={(e) => {
          if (!drag.current) return
          const fine = e.shiftKey ? 0.25 : 1
          const n = drag.current.n + ((drag.current.y - e.clientY) / 140) * fine
          onChange(clamp(Math.round(fromNorm(n) / step) * step))
        }}
        onPointerUp={() => (drag.current = null)}
        onPointerCancel={() => (drag.current = null)}
        onDoubleClick={() => onChange(defaultValue)}
        onKeyDown={(e) => {
          if (e.key === "ArrowUp" || e.key === "ArrowRight") onChange(clamp(value + step))
          else if (e.key === "ArrowDown" || e.key === "ArrowLeft") onChange(clamp(value - step))
          else return
          e.preventDefault()
        }}
      >
        <path d={arcPath(-ARC / 2, ARC / 2)} className="fill-none stroke-border" strokeWidth={track} strokeLinecap="round" />
        <path d={arcPath(zeroAngle, angle)} className="fill-none stroke-(--ctl)" strokeWidth={track} strokeLinecap="round" />
        <circle cx={C} cy={C} r={16.25} className="fill-secondary stroke-border" strokeWidth={1} />
        <circle cx={px} cy={py} r={2} className="fill-foreground" />
      </svg>
      <span
        className={cn(
          "live-number font-mono text-xs font-semibold",
          off && "text-muted-foreground",
          soloed && "text-brand-text"
        )}
      >
        {off ? offText : format(value)}
      </span>
      <ParamButtons off={off} onPower={onPower} soloed={soloed} onSolo={onSolo} />
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// Vúmetro de LEDs: verde, amarillo y rojo arriba (rojo = satura).
// Para que no caliente la compu, los LEDs están pintados fijos y encima hay una
// "tapa" que se achica con transform. No le pases el nivel por props (re-render a
// 30 fps): agarrá el elemento con `ref` y llamá a paintMeter(el, prendidos).
// Con `fill`, llena el alto disponible y los LEDs se estiran (ej: columna al costado).

export function LevelMeter({
  segments = 10,
  fill,
  className,
  ref,
}: {
  segments?: number
  fill?: boolean
  className?: string
  ref?: React.Ref<HTMLDivElement>
}) {
  return (
    <div
      ref={ref}
      data-slot="level-meter"
      data-segments={segments}
      aria-hidden="true"
      className={cn("relative flex flex-col gap-[3px] [contain:layout_paint]", fill ? "h-full" : "p-0.5", className)}
    >
      {Array.from({ length: segments }, (_, i) => (
        <span
          key={i}
          className={cn(
            fill ? "w-2 flex-1 rounded-[2px]" : "h-[7px] w-2 rounded-[2px]",
            i < 2 ? "bg-destructive" : i < 4 ? "bg-warning" : "bg-success"
          )}
        />
      ))}
      <div
        data-slot="level-meter-cover"
        className="absolute inset-0 origin-top bg-card/85 will-change-transform in-data-[variant=inset]:bg-inset/85"
      />
    </div>
  )
}

/** Prende `lit` LEDs (0 = apagado). Sólo toca el DOM si cambió. */
export function paintMeter(el: HTMLElement | null, lit: number) {
  if (!el) return
  const segments = Number(el.dataset.segments) || 10
  const n = Math.max(0, Math.min(segments, Math.round(lit)))
  if (el.dataset.lit === String(n)) return
  el.dataset.lit = String(n)
  const cover = el.querySelector<HTMLElement>('[data-slot="level-meter-cover"]')
  if (cover) cover.style.transform = `scaleY(${(segments - n) / segments})`
}

import * as React from "react"
import { cn } from "@/lib/utils"

// Panel de una sección de controles (ej: SONIDO, CONSOLA, MEZCLA):
// - variant="card" (por defecto): caja L, blanca y SIN borde, sobre el fondo de la página.
//   Regla del sistema: las cajas nunca llevan borde; se separan por color de fondo.
// - variant="inset": caja M (los controles grises de adentro pasan a blanco solos para que se vean), gris clarito sin borde (bg-inset: stone 100 en claro, un paso más claro que la tarjeta en oscuro), para ir adentro de otra caja.
// tarjeta con un título chiquito en mayúsculas y un puntito de color.
// Con `live`, el puntito es de "en vivo": aro naranja más claro mientras live=true,
// y gris cuando está en false (ej: el monitor cuando no suena nada).

export function AudioPanel({
  title,
  color,
  live,
  variant = "card",
  className,
  children,
}: {
  /** opcional: sin título, la caja no muestra la fila de arriba */
  title?: string
  color?: string
  live?: boolean
  variant?: "card" | "inset"
  className?: string
  children: React.ReactNode
}) {
  return (
    <section
      data-slot="audio-panel"
      data-variant={variant}
      className={cn(
        "flex min-w-0 flex-col", // el contenido puede crecer con flex-1 para llenar la caja
        variant === "inset"
          ? "rounded-box-m bg-inset p-box-m"
          : "rounded-box-l bg-card p-box-l",
        className
      )}
    >
      {title && (
        <h4 className="mb-3 flex items-center gap-2 eyebrow">
          <span
            className={cn(
              "dot",
              live !== undefined && "mx-0.5 transition-[background,box-shadow]"
            )}
            style={
              live === undefined
                ? { background: color ?? "var(--brand)" }
                : live
                  ? {
                      background: color ?? "var(--brand)",
                      boxShadow: `0 0 0 3px color-mix(in oklch, ${color ?? "var(--brand)"} 30%, transparent)`,
                    }
                  : { background: "var(--muted-foreground)" }
            }
          />
          {title}
        </h4>
      )}
      {children}
    </section>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { clamp, snap, useDrag } from "@/components/audio/drag"

// Dial grande: recorre de abajo a la izquierda a abajo a la derecha (270°, como una perilla).
// Las marcas son puntos grises claros de 4px. El valor va en el centro.
// Arrastrá hacia arriba/abajo (Shift = fino), flechas, doble clic = valor por defecto.
// variant "line": una línea de 4px del color de la app va llenando el borde del círculo.
// variant "fill": la banda se pinta del color de la app, con puntas redondeadas;
//   los puntos que quedan debajo se pintan del tono fuerte (orange-700 en LOOP).
// variant "dots": sin borde ni banda; se van pintando los puntos hasta el valor.
// `bipolar`: el cero está arriba, en el medio. Se llena desde ahí hacia la izquierda
//   (valores negativos) o hacia la derecha (positivos). Ej: un filtro con centro = apagado.
// Se puede arrastrar de costado (derecha = más) o para arriba (arriba = más).
// `ticks`: cuántos espacios hay entre rayitas. Para un dial "de 10 en 10" de 0 a 100: step 10 y ticks 10.

const SIZE = 140 // todos los diales miden lo mismo, en todas las apps
const ARC = 270
const START = -ARC / 2 // abajo a la izquierda
const BAND = 41 // radio de la banda donde van las marcas

function pt(r: number, deg: number): [number, number] {
  const rad = ((deg - 90) * Math.PI) / 180
  return [50 + r * Math.cos(rad), 50 + r * Math.sin(rad)]
}

function arc(r: number, from: number, to: number) {
  if (to - from < 0.5) return ""
  const [x1, y1] = pt(r, from)
  const [x2, y2] = pt(r, to)
  return `M ${x1} ${y1} A ${r} ${r} 0 ${to - from > 180 ? 1 : 0} 1 ${x2} ${y2}`
}

export function Dial({
  label,
  value,
  min,
  max,
  step = 1,
  ticks = 8,
  defaultValue,
  format = String,
  onChange,
  variant = "line",
  bipolar = false,
  color,
  className,
}: {
  label?: string
  value: number
  min: number
  max: number
  step?: number
  ticks?: number
  defaultValue?: number
  format?: (v: number) => string
  onChange: (v: number) => void
  variant?: "line" | "fill" | "dots"
  bipolar?: boolean
  color?: string
  className?: string
}) {
  const startValue = React.useRef(value)
  const drag = useDrag<HTMLDivElement>(
    () => (startValue.current = value),
    (dx, dy, e) => {
      const fine = e.shiftKey ? 0.25 : 1
      onChange(clamp(snap(startValue.current + ((dx - dy) / 200) * (max - min) * fine, step), min, max))
    }
  )
  const n = (value - min) / (max - min)
  const angle = START + n * ARC
  // desde dónde se llena: abajo a la izquierda, o arriba al medio si es bipolar
  const from = bipolar ? Math.min(0, angle) : START
  const to = bipolar ? Math.max(0, angle) : angle
  const filled = bipolar ? Math.abs(angle) > 0.5 : n > 0
  const size = SIZE
  const edgeW = (4 * 100) / size // 4px reales, sea cual sea el tamaño del dial
  const edgeR = 50 - edgeW / 2
  const dotR = (2 * 100) / size // punto de 4px

  return (
    <div
      data-slot="dial"
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "relative shrink-0 cursor-ns-resize touch-none rounded-full outline-none select-none focus-visible:ring-4 focus-visible:ring-(--ctl)/30",
        className
      )}
      style={
        {
          width: size,
          height: size,
          "--ctl": color ?? "var(--brand)",
          "--ctl-strong": color ? `color-mix(in oklch, ${color} 78%, black)` : "var(--brand-strong)",
        } as React.CSSProperties
      }
      {...drag}
      onDoubleClick={() => defaultValue !== undefined && onChange(defaultValue)}
      onKeyDown={(e) => {
        if (e.key === "ArrowUp" || e.key === "ArrowRight") onChange(clamp(value + step, min, max))
        else if (e.key === "ArrowDown" || e.key === "ArrowLeft") onChange(clamp(value - step, min, max))
        else return
        e.preventDefault()
      }}
    >
      <svg viewBox="0 0 100 100" className="absolute inset-0 size-full">
        <circle cx="50" cy="50" r="49" className="fill-card stroke-border" strokeWidth="0.75" />
        {variant === "fill" &&
          filled && (
            <path d={arc(BAND, from, to)} className="fill-none stroke-(--ctl)" strokeWidth="9" strokeLinecap="round" />
          )}
        <circle cx="50" cy="50" r="33" className="fill-secondary" />
        {Array.from({ length: ticks + 1 }, (_, i) => {
          const a = START + (i / ticks) * ARC
          const [x, y] = pt(BAND, a)
          const covered = variant !== "line" && filled && a >= from - 0.01 && a <= to + 0.01
          const on = variant === "fill" ? "fill-(--ctl-strong)" : "fill-(--ctl)"
          return (
            <circle key={i} cx={x} cy={y} r={dotR} className={covered ? on : "fill-muted-foreground/40"} />
          )
        })}
        {variant === "line" && filled && (
          <path d={arc(edgeR, from, to)} className="fill-none stroke-(--ctl)" strokeWidth={edgeW} strokeLinecap="round" />
        )}
      </svg>
      <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
        <span className="live-number leading-none font-light tracking-tight" style={{ fontSize: size * 0.2 }}>
          {format(value)}
        </span>
        {label && <span className="mt-1 text-[11px] text-muted-foreground">{label}</span>}
      </div>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { Minus, Plus } from "lucide-react"
import { clamp, snap, useDrag } from "@/components/audio/drag"
import { Button } from "@/components/ui/button"

// Sintonizador tipo radio: número grande arriba y una regla que se arrastra
// de costado debajo de una aguja fija. Ideal para valores precisos (BPM, frecuencia).
// Los ceros de adelante del número se ven apagados.
// Con `stepper`, aparecen botones − y + a los costados del número para ajustar de a uno.
// `children` va centrado abajo de la regla (ej: un botón Tap).

export function Tuner({
  label,
  value,
  min,
  max,
  step = 1,
  major = 10,
  digits = 3,
  decimals = 0,
  pxPerStep = 8,
  onChange,
  color,
  numberClassName,
  caption,
  stepper = false,
  className,
  children,
}: {
  label?: string
  value: number
  min: number
  max: number
  /** cuánto vale cada rayita */
  step?: number
  /** cada cuánto va una rayita larga con número */
  major?: number
  /** dígitos enteros que se muestran (con ceros apagados) */
  digits?: number
  decimals?: number
  pxPerStep?: number
  onChange: (v: number) => void
  color?: string
  /** clases extra para el número (ej: "font-readout") */
  numberClassName?: string
  /** texto debajo del número en lugar de `label` (ej: <><b>BPM</b> · bailable</>) */
  caption?: React.ReactNode
  stepper?: boolean
  className?: string
  children?: React.ReactNode
}) {
  const box = React.useRef<HTMLDivElement>(null)
  const [width, setWidth] = React.useState(320)
  React.useLayoutEffect(() => {
    const el = box.current
    if (!el) return
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  const startValue = React.useRef(value)
  const drag = useDrag<HTMLDivElement>(
    () => (startValue.current = value),
    (dx) =>
      onChange(
        clamp(
          snap(startValue.current - (dx / pxPerStep) * step, step),
          min,
          max
        )
      )
  )

  const fixed = value.toFixed(decimals)
  const [int, dec] = fixed.split(".")
  const padded = int.padStart(digits, "0")
  const firstReal = padded.search(/[1-9]/)
  const cut = firstReal === -1 ? digits - 1 : firstReal

  const half = Math.ceil(width / 2 / pxPerStep) + 1
  const center = Math.round(value / step)
  const ticks = []
  for (let k = center - half; k <= center + half; k++) {
    const v = k * step
    if (v < min - 1e-9 || v > max + 1e-9) continue
    const x = width / 2 + (v - value) * (pxPerStep / step)
    const isMajor = Math.abs(v / major - Math.round(v / major)) < 1e-6
    const isMid =
      !isMajor && Math.abs((2 * v) / major - Math.round((2 * v) / major)) < 1e-6
    ticks.push(
      <div
        key={k}
        className="absolute top-0"
        style={{ transform: `translateX(${x}px)` }}
      >
        <div
          className={cn(
            "w-px -translate-x-1/2",
            isMajor
              ? "h-7 bg-foreground/70"
              : isMid
                ? "h-5 bg-muted-foreground/60"
                : "h-3.5 bg-muted-foreground/40"
          )}
        />
        {isMajor && (
          <div className="mt-1.5 -translate-x-1/2 font-mono text-[10px] text-muted-foreground">
            {Number(v.toFixed(decimals))}
          </div>
        )}
      </div>
    )
  }

  return (
    <div
      data-slot="tuner"
      className={cn(
        "flex w-full flex-col items-center gap-1 select-none",
        className
      )}
      style={{ "--ctl": color ?? "var(--brand)" } as React.CSSProperties}
    >
      {/* número + texto: si el sintonizador tiene alto de sobra (flex-1), quedan centrados
          en ese espacio y la regla queda abajo */}
      <div className="flex w-full flex-1 flex-col items-center justify-center gap-1">
        <div className="flex w-full items-center justify-center gap-2">
          {stepper && (
            <Button
              size="icon"
              variant="secondary"
              aria-label="Decrease"
              onClick={() =>
                onChange(clamp(snap(value - step, step), min, max))
              }
            >
              <Minus />
            </Button>
          )}
          <div
            className={cn(
              "flex-1 text-center text-6xl leading-none font-light live-number tracking-tighter",
              numberClassName
            )}
          >
            <span className="text-muted-foreground/40">
              {padded.slice(0, cut)}
            </span>
            {padded.slice(cut)}
            {dec !== undefined && <>.{dec}</>}
          </div>
          {stepper && (
            <Button
              size="icon"
              variant="secondary"
              aria-label="Increase"
              onClick={() =>
                onChange(clamp(snap(value + step, step), min, max))
              }
            >
              <Plus />
            </Button>
          )}
        </div>
        {caption ? (
          <div className="text-sm whitespace-nowrap text-muted-foreground">
            {caption}
          </div>
        ) : (
          label && <div className="text-sm text-muted-foreground">{label}</div>
        )}
      </div>
      <div
        ref={box}
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        className="relative mt-3 h-14 w-full cursor-ew-resize touch-none overflow-hidden rounded-md [mask-image:linear-gradient(to_right,transparent,black_18%,black_82%,transparent)] outline-none focus-visible:bg-accent"
        {...drag}
        onWheel={(e) => {
          const d =
            Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY
          onChange(clamp(snap(value + Math.sign(d) * step, step), min, max))
        }}
        onKeyDown={(e) => {
          if (e.key === "ArrowRight" || e.key === "ArrowUp")
            onChange(clamp(snap(value + step, step), min, max))
          else if (e.key === "ArrowLeft" || e.key === "ArrowDown")
            onChange(clamp(snap(value - step, step), min, max))
          else return
          e.preventDefault()
        }}
      >
        {ticks}
        <div className="absolute inset-y-0 left-1/2 w-0.5 -translate-x-1/2 rounded-full bg-(--ctl)" />
      </div>
      {children && <div className="mt-2 flex justify-center">{children}</div>}
    </div>
  )
}

import { cn } from "@/lib/utils"

// Perilla de posiciones fijas (como "33 · 45 · 78" de un tocadiscos).
// Para elegir entre pocas opciones: compás, forma de onda, velocidad.
// Clic en una opción para ir directo; clic en la perilla o flechas para avanzar.
// La posición se marca con un punto de 4px y la opción elegida se pinta del color de la app (orange-600 en LOOP).

export function SelectorKnob<T extends string | number>({
  label,
  options,
  value,
  onChange,
  size = 72,
  className,
}: {
  label?: string
  options: { value: T; label: string }[]
  value: T
  onChange: (v: T) => void
  size?: number
  className?: string
}) {
  const count = options.length
  const spread = Math.min(270, Math.max(0, (count - 1) * 45))
  const angleOf = (i: number) => (count <= 1 ? 0 : -spread / 2 + (i / (count - 1)) * spread)
  const idx = Math.max(0, options.findIndex((o) => o.value === value))
  const box = size + 64
  const c = box / 2
  const go = (i: number) => onChange(options[(i + count) % count].value)

  return (
    <div data-slot="selector-knob" className={cn("flex flex-col items-center", className)}>
      <div className="relative" style={{ width: box, height: box }}>
        {options.map((o, i) => {
          const rad = ((angleOf(i) - 90) * Math.PI) / 180
          const r = size / 2 + 18
          return (
            <button
              key={String(o.value)}
              type="button"
              onClick={() => go(i)}
              className={cn(
                "absolute -translate-x-1/2 -translate-y-1/2 rounded-md px-1 font-mono text-xs transition-colors",
                i === idx ? "font-semibold text-brand" : "text-muted-foreground hover:text-foreground"
              )}
              style={{ left: c + r * Math.cos(rad), top: c + r * Math.sin(rad) }}
            >
              {o.label}
            </button>
          )
        })}
        <button
          type="button"
          aria-label={label ? `${label}: ${options[idx]?.label}` : options[idx]?.label}
          onClick={() => go(idx + 1)}
          onKeyDown={(e) => {
            if (e.key === "ArrowRight" || e.key === "ArrowUp") go(idx + 1)
            else if (e.key === "ArrowLeft" || e.key === "ArrowDown") go(idx - 1)
            else return
            e.preventDefault()
          }}
          className="absolute rounded-full bg-foreground outline-none focus-visible:ring-4 focus-visible:ring-brand/30"
          style={{ left: c - size / 2, top: c - size / 2, width: size, height: size }}
        >
          <span
            className="absolute inset-0 transition-transform duration-200"
            style={{ transform: `rotate(${angleOf(idx)}deg)` }}
          >
            <span className="dot absolute top-[14%] left-1/2 -translate-x-1/2 bg-background" />
          </span>
        </button>
      </div>
      {label && <span className="-mt-3 text-sm text-muted-foreground">{label}</span>}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { clamp, snap } from "@/components/audio/drag"
import { PowerButton } from "@/components/audio/param-buttons"

// Barra vertical gruesa: tocás o arrastrás a la altura que querés. El número va adentro.
// - Se pinta del color de la app al pasar el mouse, mientras la movés y cuando está al máximo.
// - En 0 se ve rayada.
// - Con `accent`, el relleno es siempre del color de la app (para la barra principal, ej: volumen general).
// - Con `onPower` aparece abajo un botón ⏻ que apaga la variable entera (rayada + OFF).

const STRIPES =
  "repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in oklch, var(--muted-foreground) 28%, transparent) 5px 6px)"

export function BarFader({
  label,
  value,
  min = 0,
  max = 1,
  step = 0.01,
  defaultValue,
  format = String,
  onChange,
  off,
  onPower,
  accent = false,
  color,
  height = 160,
  width = 56,
  className,
}: {
  label?: string
  value: number
  min?: number
  max?: number
  step?: number
  defaultValue?: number
  format?: (v: number) => string
  onChange: (v: number) => void
  off?: boolean
  onPower?: () => void
  accent?: boolean
  color?: string
  height?: number
  width?: number
  className?: string
}) {
  const [dragging, setDragging] = React.useState(false)
  const n = (value - min) / (max - min)
  const empty = n <= 0.0001
  const full = n >= 0.9999
  const setFrom = (e: React.PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect()
    const p = clamp(1 - (e.clientY - r.top) / r.height, 0, 1)
    onChange(clamp(snap(min + p * (max - min), step), min, max))
  }
  const inside = n > 0.2
  const lit = accent || dragging || full

  return (
    <div
      data-slot="bar-fader"
      className={cn("flex flex-col items-center gap-2", className)}
      style={{ "--ctl": color ?? "var(--brand)" } as React.CSSProperties}
    >
      <div
        role="slider"
        tabIndex={off ? -1 : 0}
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        aria-disabled={off}
        className={cn(
          "group/bar relative touch-none overflow-hidden rounded-xl bg-secondary in-data-[variant=inset]:bg-card outline-none select-none focus-visible:ring-4 focus-visible:ring-(--ctl)/30",
          off ? "cursor-not-allowed" : "cursor-ns-resize"
        )}
        style={{ width, height, ...((off || empty) && { backgroundImage: STRIPES }) }}
        onPointerDown={(e) => {
          if (off) return
          e.currentTarget.setPointerCapture(e.pointerId)
          setDragging(true)
          setFrom(e)
        }}
        onPointerMove={(e) => dragging && setFrom(e)}
        onPointerUp={() => setDragging(false)}
        onPointerCancel={() => setDragging(false)}
        onDoubleClick={() => !off && defaultValue !== undefined && onChange(defaultValue)}
        onKeyDown={(e) => {
          if (off) return
          if (e.key === "ArrowUp") onChange(clamp(value + step, min, max))
          else if (e.key === "ArrowDown") onChange(clamp(value - step, min, max))
          else return
          e.preventDefault()
        }}
      >
        {!off && !empty && (
          <div
            className={cn(
              "absolute inset-x-0 bottom-0 rounded-xl transition-colors",
              lit ? "bg-(--ctl)" : "bg-foreground group-hover/bar:bg-(--ctl)"
            )}
            style={{ height: `${n * 100}%` }}
          />
        )}
        <span
          className={cn(
            "live-number absolute inset-x-0 text-center font-mono text-xs font-semibold transition-colors",
            off || !inside
              ? off
                ? "text-muted-foreground"
                : "text-foreground"
              : lit
                ? "text-brand-foreground"
                : "text-background group-hover/bar:text-brand-foreground"
          )}
          style={
            off
              ? { top: "45%" }
              : inside
                ? { bottom: `calc(${n * 100}% - 1.6rem)` }
                : { bottom: `calc(${n * 100}% + 0.4rem)` }
          }
        >
          {off ? "OFF" : format(value)}
        </span>
      </div>
      {label && <span className="eyebrow">{label}</span>}
      {onPower && <PowerButton off={off} onToggle={onPower} />}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { clamp } from "@/components/audio/drag"

// Pad circular: movés un punto y controlás DOS cosas a la vez
// (de izquierda a derecha = X, de abajo hacia arriba = Y). Valores de 0 a 1.
// Doble clic: vuelve al centro (o a los valores por defecto).

export function XYPad({
  x,
  y,
  onChange,
  labelX,
  labelY,
  defaultX = 0.5,
  defaultY = 0.5,
  size = 168,
  color,
  className,
}: {
  x: number
  y: number
  onChange: (x: number, y: number) => void
  labelX?: string
  labelY?: string
  defaultX?: number
  defaultY?: number
  size?: number
  color?: string
  className?: string
}) {
  const dragging = React.useRef(false)
  const puck = Math.round(size * 0.2)
  const R = size / 2 - puck / 2 - 4

  const setFrom = (e: React.PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect()
    let dx = e.clientX - (r.left + r.width / 2)
    let dy = e.clientY - (r.top + r.height / 2)
    const d = Math.hypot(dx, dy)
    if (d > R) {
      dx = (dx / d) * R
      dy = (dy / d) * R
    }
    onChange(clamp((dx / R + 1) / 2, 0, 1), clamp((1 - dy / R) / 2, 0, 1))
  }

  // posición del punto (si el valor guardado cae fuera del círculo, lo acerca)
  let px = (x * 2 - 1) * R
  let py = -(y * 2 - 1) * R
  const d = Math.hypot(px, py)
  if (d > R) {
    px = (px / d) * R
    py = (py / d) * R
  }

  return (
    <div data-slot="xy-pad" className={cn("flex flex-col items-center gap-2", className)}>
      <div
        role="group"
        aria-label={[labelX, labelY].filter(Boolean).join(" y ")}
        className="relative cursor-crosshair touch-none rounded-full bg-secondary in-data-[variant=inset]:bg-card select-none"
        style={{ width: size, height: size }}
        onPointerDown={(e) => {
          e.currentTarget.setPointerCapture(e.pointerId)
          dragging.current = true
          setFrom(e)
        }}
        onPointerMove={(e) => dragging.current && setFrom(e)}
        onPointerUp={() => (dragging.current = false)}
        onPointerCancel={() => (dragging.current = false)}
        onDoubleClick={() => onChange(defaultX, defaultY)}
      >
        <div className="absolute inset-[22%] rounded-full border border-border" />
        <div className="dot absolute top-1/2 left-1/2 -translate-1/2 bg-foreground" />
        <div
          className="absolute rounded-full shadow-sm"
          style={{
            width: puck,
            height: puck,
            left: size / 2 + px - puck / 2,
            top: size / 2 + py - puck / 2,
            background: color ?? "var(--brand)",
          }}
        />
      </div>
      {(labelX || labelY) && (
        <div className="flex gap-3 font-mono text-[11px] text-muted-foreground">
          {labelX && (
            <span>
              {labelX} <span className="live-number text-foreground">{Math.round(x * 100)}%</span>
            </span>
          )}
          {labelY && (
            <span>
              {labelY} <span className="live-number text-foreground">{Math.round(y * 100)}%</span>
            </span>
          )}
        </div>
      )}
    </div>
  )
}

